const tutorial={n:4,walls:[],start:[0,5],goal:[11,15],par:2};
const stages=[tutorial,LEVELS[0],LEVELS[3],LEVELS[4],LEVELS[2],...EXTRA_LEVELS];
let level=0,p=[],history=[],won=false,best=JSON.parse(localStorage.getItem('together-best')||'{}');
const $=s=>document.querySelector(s),names=['Learn in two moves','A small problem','The long way around','No easy way home','Everything is connected','Crossed paths','The holding pattern','Thread the needle','A little cooperation','Wrong turn, right idea','The waiting room','Perfect interference','Three-body problem','The narrow escape','Almost together','The last detour','Tangled intentions','The long goodbye','A beautiful mistake','One final wrong turn'],colors=['red','blue','yellow'],pieces=['●','◆','■'],rings=['◯','◇','□'];
function step(pos,d,g){let [dx,dy]=[[0,-1],[1,0],[0,1],[-1,0]][d],r=[...pos];let order=r.map((_,i)=>i).sort((a,b)=>(r[b]%g.n*dx+Math.floor(r[b]/g.n)*dy)-(r[a]%g.n*dx+Math.floor(r[a]/g.n)*dy));for(let i of order)while(true){let x=r[i]%g.n+dx,y=Math.floor(r[i]/g.n)+dy,q=y*g.n+x;if(x<0||y<0||x>=g.n||y>=g.n||g.walls.includes(q)||r.includes(q))break;r[i]=q}return r}
function same(a,b){return a.join(',')===b.join(',')}
function load(i){level=i;p=[...stages[i].start];history=[];won=false;draw();$('#notice').textContent=i===0?'Try → then ↓. Every piece moves.':''}
function draw(){let g=stages[level];$('#levels').innerHTML=stages.map((_,i)=>`<button class="${i===level?'selected':''}" onclick="load(${i})" aria-label="Level ${i+1}" aria-pressed="${i===level}">${best[i]?'✓':i+1}</button>`).join('');$('#progress').textContent=Object.keys(best).length+' / '+stages.length+' solved · '+(best[level]?'Your best: '+best[level]+' moves':'Shortest solution: '+g.par+' moves');$('#difficulty').textContent=(['THE BASICS','HARD','VERY HARD','EXPERT','BRUTAL'][level]||'BRUTAL / CHAPTER '+Math.ceil((level+1)/5));$('#name').textContent=names[level];$('#moves').textContent=history.length;$('#board').style.gridTemplateColumns=`repeat(${g.n},1fr)`;$('#board').innerHTML=Array.from({length:g.n*g.n},(_,j)=>{let t=g.goal.indexOf(j),i=p.indexOf(j);return `<div class="tile ${g.walls.includes(j)?'wall':''} ${i>=0&&i===t?'matched':''}">${t>=0?`<span class="target ${colors[t]}">${rings[t]}</span>`:''}${i>=0?`<span class="piece ${colors[i]}">${pieces[i]}</span>`:''}</div>`}).join('')}
function act(d){if(won)return;let q=step(p,d,stages[level]);if(same(p,q)){$('#notice').textContent='Blocked. Try another direction.';return}history.push([...p]);p=q;draw();$('#notice').textContent='';if(same(p,stages[level].goal)){won=true;best[level]=Math.min(best[level]||Infinity,history.length);localStorage.setItem('together-best',JSON.stringify(best));draw();$('#notice').innerHTML='✓ All pieces home!'+(level<stages.length-1?`<button onclick="load(${level+1})">Next level →</button>`:' You solved the collection.')}}
function undo(){if(!history.length)return;p=history.pop();won=false;draw();$('#notice').textContent='Move undone.'}
function solve(start,g){let queue=[start],seen=new Set([start.join(',')]),prev=new Map(),goal=null;for(let h=0;h<queue.length;h++){let s=queue[h];if(same(s,g.goal)){goal=s.join(',');break}for(let d=0;d<4;d++){let t=step(s,d,g),k=t.join(',');if(!seen.has(k)){seen.add(k);prev.set(k,[s.join(','),d]);queue.push(t)}}}if(goal===null)return null;let path=[];while(prev.has(goal)){let [old,d]=prev.get(goal);path.push(d);goal=old}return path.reverse()}
function hint(){if(won)return;let path=solve(p,stages[level]);$('#notice').textContent=path===null?'No path from here. Undo or restart.':path.length?'Try '+['↑ up','→ right','↓ down','← left'][path[0]]+' · '+path.length+' moves from here.':'All pieces home.'}
document.addEventListener('keydown',e=>{let d={ArrowUp:0,w:0,ArrowRight:1,d:1,ArrowDown:2,s:2,ArrowLeft:3,a:3};if(d[e.key]!==undefined){e.preventDefault();act(d[e.key])}if(e.key==='z')undo()});let touch=null;$('#board').addEventListener('pointerdown',e=>{touch=[e.clientX,e.clientY];$('#board').setPointerCapture(e.pointerId)});$('#board').addEventListener('pointerup',e=>{if(!touch)return;let dx=e.clientX-touch[0],dy=e.clientY-touch[1];touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))<20)return;act(Math.abs(dx)>Math.abs(dy)?dx>0?1:3:dy>0?2:0)});$('#board').addEventListener('pointercancel',()=>touch=null);load(0);
